#include <bits/stdc++.h>
using namespace std;

const double INF = 1e18;

struct Point {
    double x, y;
    Point() {}
    Point(double x, double y) : x(x), y(y) {}
    Point operator+(const Point& p) const { return Point(x + p.x, y + p.y); }
    Point operator-(const Point& p) const { return Point(x - p.x, y - p.y); }
    double dot(const Point& p) const { return x * p.x + y * p.y; }
    double cross(const Point& p) const { return x * p.y - y * p.x; }
    double dist(const Point& p) const {
        double dx = x - p.x, dy = y - p.y;
        return sqrt(dx*dx + dy*dy);
    }
};

// Check if point q is on segment pr
bool onSegment(Point p, Point q, Point r) {
    if (q.x <= max(p.x, r.x) && q.x >= min(p.x, r.x) &&
        q.y <= max(p.y, r.y) && q.y >= min(p.y, r.y))
        return true;
    return false;
}

// Orientation of triplet (p, q, r)
int orientation(Point p, Point q, Point r) {
    double val = (q.y - p.y) * (r.x - q.x) - (q.x - p.x) * (r.y - q.y);
    if (fabs(val) < 1e-12) return 0;  // collinear
    return (val > 0) ? 1 : 2; // 1 clockwise, 2 counterclockwise
}

// Check if segments p1q1 and p2q2 intersect
bool segmentsIntersect(Point p1, Point q1, Point p2, Point q2) {
    int o1 = orientation(p1, q1, p2);
    int o2 = orientation(p1, q1, q2);
    int o3 = orientation(p2, q2, p1);
    int o4 = orientation(p2, q2, q1);
    if (o1 != o2 && o3 != o4) return true;
    if (o1 == 0 && onSegment(p1, p2, q1)) return true;
    if (o2 == 0 && onSegment(p1, q2, q1)) return true;
    if (o3 == 0 && onSegment(p2, p1, q2)) return true;
    if (o4 == 0 && onSegment(p2, q1, q2)) return true;
    return false;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    // Each pentacle has 5 points, store them
    vector<vector<Point>> pentacles(N, vector<Point>(5));
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < 5; j++) {
            cin >> pentacles[i][j].x >> pentacles[i][j].y;
        }
    }

    Point start, end;
    cin >> start.x >> start.y >> end.x >> end.y;

    // Collect all vertices: start, end, and all pentacle points
    vector<Point> vertices;
    vertices.push_back(start);
    vertices.push_back(end);
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < 5; j++) {
            vertices.push_back(pentacles[i][j]);
        }
    }

    int V = vertices.size();
    // Build adjacency matrix with edge weights
    vector<vector<double>> dist(V, vector<double>(V, INF));
    for (int i = 0; i < V; i++) dist[i][i] = 0;

    // For each pair of vertices, check if direct line is blocked by any pentacle edge
    for (int i = 0; i < V; i++) {
        for (int j = i+1; j < V; j++) {
            Point a = vertices[i], b = vertices[j];
            bool blocked = false;
            // Check against all pentacle edges
            for (int p = 0; p < N && !blocked; p++) {
                for (int k = 0; k < 5; k++) {
                    int next = (k+1)%5;
                    Point c = pentacles[p][k], d = pentacles[p][next];
                    // If the segment is part of the pentacle edge, we can travel along it for free
                    // But we only consider blocking if they intersect at an interior point
                    // Actually, we need to check if the direct line crosses the pentacle edge
                    // But if the line goes exactly along the edge, it's allowed (no energy cost)

                    // Check if a-b and c-d intersect properly
                    if (segmentsIntersect(a, b, c, d)) {
                        // Check if they share an endpoint - that's allowed
                        bool shareEndpoint = false;
                        if ((a.x == c.x && a.y == c.y) || (a.x == d.x && a.y == d.y) ||
                            (b.x == c.x && b.y == c.y) || (b.x == d.x && b.y == d.y))
                            shareEndpoint = true;

                        if (!shareEndpoint) {
                            // Also check if they are collinear and overlapping
                            if (orientation(a, b, c) == 0 && orientation(a, b, d) == 0) {
                                // Both points on line, check if segments overlap
                                // If they share more than a point, it's blocked unless it's exactly the edge
                                // We'll consider it blocked if the intersection is more than a point
                                // For simplicity: if collinear and overlapping and not just touching at endpoints
                                if (onSegment(a, c, b) || onSegment(a, d, b) ||
                                    onSegment(c, a, d) || onSegment(c, b, d)) {
                                    // Check if they just touch at endpoints
                                    if (!((a.x == c.x && a.y == c.y) || (a.x == d.x && a.y == d.y) ||
                                          (b.x == c.x && b.y == c.y) || (b.x == d.x && b.y == d.y)))
                                        blocked = true;
                                }
                            } else {
                                blocked = true;
                            }
                        }
                    }
                }
            }
            if (!blocked) {
                double d = a.dist(b);
                dist[i][j] = dist[j][i] = d;
            }
        }
    }

    // Now add edges along pentacle edges (cost 0)
    for (int p = 0; p < N; p++) {
        for (int k = 0; k < 5; k++) {
            int next = (k+1)%5;
            // Find indices of these two points in vertices
            int idx1 = -1, idx2 = -1;
            Point pt1 = pentacles[p][k];
            Point pt2 = pentacles[p][next];
            for (int v = 0; v < V; v++) {
                if (fabs(vertices[v].x - pt1.x) < 1e-12 && fabs(vertices[v].y - pt1.y) < 1e-12)
                    idx1 = v;
                if (fabs(vertices[v].x - pt2.x) < 1e-12 && fabs(vertices[v].y - pt2.y) < 1e-12)
                    idx2 = v;
            }
            if (idx1 != -1 && idx2 != -1) {
                dist[idx1][idx2] = dist[idx2][idx1] = 0.0;
            }
        }
    }

    // Floyd-Warshall
    for (int k = 0; k < V; k++) {
        for (int i = 0; i < V; i++) {
            for (int j = 0; j < V; j++) {
                if (dist[i][k] + dist[k][j] < dist[i][j] - 1e-12) {
                    dist[i][j] = dist[i][k] + dist[k][j];
                }
            }
        }
    }

    // Output distance from start (index 0) to end (index 1)
    cout << fixed << setprecision(15) << dist[0][1] << "\n";

    return 0;
}

