#include <bits/stdc++.h>
using namespace std;

struct DSU {
    vector<int> p, sz;
    DSU(int n = 0) { init(n); }
    void init(int n) {
        p.resize(n);
        sz.assign(n, 1);
        iota(p.begin(), p.end(), 0);
    }
    int find(int x) {
        if (p[x] == x) return x;
        return p[x] = find(p[x]);
    }
    void unite(int a, int b) {
        a = find(a); b = find(b);
        if (a == b) return;
        if (sz[a] < sz[b]) swap(a, b);
        p[b] = a;
        sz[a] += sz[b];
    }
};

struct Point {
    double x, y;
};

static const double EPS = 1e-10;

double cross(const Point& a, const Point& b, const Point& c) {
    return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
}

bool onSegment(const Point& a, const Point& b, const Point& p) {
    if (fabs(cross(a, b, p)) > EPS) return false;
    return min(a.x, b.x) - EPS <= p.x && p.x <= max(a.x, b.x) + EPS &&
           min(a.y, b.y) - EPS <= p.y && p.y <= max(a.y, b.y) + EPS;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<array<Point, 5>> stars(n);
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < 5; j++) cin >> stars[i][j].x >> stars[i][j].y;
    }

    Point S, T;
    cin >> S.x >> S.y >> T.x >> T.y;

    // Pentacle edges: connect i -> i+2 mod 5
    vector<pair<Point, Point>> segs;
    segs.reserve(n * 5);
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < 5; j++) {
            int k = (j + 2) % 5;
            segs.push_back({stars[i][j], stars[i][k]});
        }
    }

    int m = (int)segs.size();
    DSU dsu(m);

    // Segments that intersect belong to same zero-cost component.
    auto sgn = [&](double v) {
        if (v > EPS) return 1;
        if (v < -EPS) return -1;
        return 0;
    };

    auto intersect = [&](const Point& a, const Point& b, const Point& c, const Point& d) {
        double c1 = cross(a, b, c), c2 = cross(a, b, d);
        double c3 = cross(c, d, a), c4 = cross(c, d, b);
        int s1 = sgn(c1), s2 = sgn(c2), s3 = sgn(c3), s4 = sgn(c4);

        if (s1 == 0 && onSegment(a, b, c)) return true;
        if (s2 == 0 && onSegment(a, b, d)) return true;
        if (s3 == 0 && onSegment(c, d, a)) return true;
        if (s4 == 0 && onSegment(c, d, b)) return true;
        return (s1 * s2 < 0 && s3 * s4 < 0);
    };

    for (int i = 0; i < m; i++) {
        for (int j = i + 1; j < m; j++) {
            if (intersect(segs[i].first, segs[i].second, segs[j].first, segs[j].second)) {
                dsu.unite(i, j);
            }
        }
    }

    // Build components.
    map<int, int> compId;
    for (int i = 0; i < m; i++) {
        int r = dsu.find(i);
        if (!compId.count(r)) {
            int id = (int)compId.size();
            compId[r] = id;
        }
    }
    int C = (int)compId.size();

    vector<vector<Point>> compPoints(C);
    for (int i = 0; i < m; i++) {
        int id = compId[dsu.find(i)];
        compPoints[id].push_back(segs[i].first);
        compPoints[id].push_back(segs[i].second);
    }

    // Remove duplicate points in each component.
    for (int i = 0; i < C; i++) {
        auto &v = compPoints[i];
        vector<Point> u;
        for (auto &p : v) {
            bool found = false;
            for (auto &q : u) {
                if (fabs(p.x - q.x) < EPS && fabs(p.y - q.y) < EPS) {
                    found = true;
                    break;
                }
            }
            if (!found) u.push_back(p);
        }
        v.swap(u);
    }

    auto pointToComp = [&](const Point& p) -> int {
        for (int i = 0; i < m; i++) {
            if (onSegment(segs[i].first, segs[i].second, p)) {
                return compId[dsu.find(i)];
            }
        }
        return -1;
    };

    int sComp = pointToComp(S);
    int tComp = pointToComp(T);

    int SRC = C, DST = C + 1;
    int N = C + 2;

    vector<vector<pair<int, double>>> g(N);

    auto addEdge = [&](int u, int v, double w) {
        g[u].push_back({v, w});
        g[v].push_back({u, w});
    };

    // Between components: minimum distance between any vertices of each component.
    for (int i = 0; i < C; i++) {
        for (int j = i + 1; j < C; j++) {
            double best = 1e100;
            for (auto &a : compPoints[i]) {
                for (auto &b : compPoints[j]) {
                    double dx = a.x - b.x, dy = a.y - b.y;
                    best = min(best, sqrt(dx * dx + dy * dy));
                }
            }
            addEdge(i, j, best);
        }
    }

    // Connect S and T.
    if (sComp != -1) addEdge(SRC, sComp, 0.0);
    else {
        for (int i = 0; i < C; i++) {
            double best = 1e100;
            for (auto &p : compPoints[i]) {
                double dx = S.x - p.x, dy = S.y - p.y;
                best = min(best, sqrt(dx * dx + dy * dy));
            }
            addEdge(SRC, i, best);
        }
    }

    if (tComp != -1) addEdge(DST, tComp, 0.0);
    else {
        for (int i = 0; i < C; i++) {
            double best = 1e100;
            for (auto &p : compPoints[i]) {
                double dx = T.x - p.x, dy = T.y - p.y;
                best = min(best, sqrt(dx * dx + dy * dy));
            }
            addEdge(DST, i, best);
        }
    }

    // Direct S-T move.
    {
        double dx = S.x - T.x, dy = S.y - T.y;
        addEdge(SRC, DST, sqrt(dx * dx + dy * dy));
    }

    // Dijkstra
    vector<double> dist(N, 1e100);
    priority_queue<pair<double,int>, vector<pair<double,int>>, greater<pair<double,int>>> pq;
    dist[SRC] = 0.0;
    pq.push({0.0, SRC});

    while (!pq.empty()) {
        auto [d, u] = pq.top();
        pq.pop();
        if (d > dist[u] + EPS) continue;
        if (u == DST) break;
        for (auto [v, w] : g[u]) {
            if (dist[v] > dist[u] + w + EPS) {
                dist[v] = dist[u] + w;
                pq.push({dist[v], v});
            }
        }
    }

    cout << fixed << setprecision(10) << dist[DST] << '\n';
    return 0;
}

