typedef struct {
    double x, y;
} Point;

static double dist(Point a, Point b) {
    double dx = a.x - b.x;
    double dy = a.y - b.y;
    return sqrt(dx * dx + dy * dy);
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    Point *p = (Point *)malloc(sizeof(Point) * n);
    for (int i = 0; i < n; i++) {
        scanf("%lf %lf", &p[i].x, &p[i].y);
    }

    if (n <= 1) {
        printf("0.0000000000\n");
        free(p);
        return 0;
    }

    /*
      Standard shortest path on complete graph:
      - Moving along edges of a pentagram is free.
      - For a regular 5-point star, each star is a connected figure, so all 5 vertices
        belonging to the same pentagram are mutually reachable at zero cost.
      Therefore, vertices are grouped by 5 consecutive points.
      Cost between different groups is Euclidean distance.
      We run Dijkstra on groups, but since intra-group cost is zero, it is enough
      to keep vertex-level distances with zero-cost edges inside each group.
    */

    double *d = (double *)malloc(sizeof(double) * n);
    char *used = (char *)calloc(n, sizeof(char));

    const double INF = 1e100;
    for (int i = 0; i < n; i++) d[i] = INF;
    d[0] = 0.0;

    for (int it = 0; it < n; it++) {
        int v = -1;
        for (int i = 0; i < n; i++) {
            if (!used[i] && (v == -1 || d[i] < d[v])) v = i;
        }
        if (v == -1) break;
        used[v] = 1;

        int gv = v / 5;
        int l = gv * 5;
        int r = l + 5;
        if (r > n) r = n;

        // zero-cost moves inside the same pentagram
        for (int u = l; u < r; u++) {
            if (d[u] > d[v]) d[u] = d[v];
        }

        // moves to all other vertices
        for (int u = 0; u < n; u++) {
            double nd = d[v] + dist(p[v], p[u]);
            if (nd < d[u]) d[u] = nd;
        }
    }

    printf("%.10f\n", d[n - 1]);

    free(p);
    free(d);
    free(used);
    return 0;
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        // Each pentacle: center x, y and radius
        double[][] centers = new double[N][2];
        double[] radii = new double[N];
        for (int i = 0; i < N; i++) {
            centers[i][0] = sc.nextDouble();
            centers[i][1] = sc.nextDouble();
            radii[i] = sc.nextDouble();
        }
        double vegaX = sc.nextDouble(), vegaY = sc.nextDouble();
        double altX = sc.nextDouble(), altY = sc.nextDouble();

        // Build graph: N*5 + 2 nodes
        int total = N * 5 + 2;
        int vegaNode = N * 5, altNode = N * 5 + 1;
        double[][] pts = new double[total][2];
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < 5; j++) {
                double angle = Math.PI / 2 + j * 2 * Math.PI / 5;
                pts[i*5+j][0] = centers[i][0] + radii[i] * Math.cos(angle);
                pts[i*5+j][1] = centers[i][1] + radii[i] * Math.sin(angle);
            }
        }
        pts[vegaNode] = new double[]{vegaX, vegaY};
        pts[altNode] = new double[]{altX, altY};

        // Dijkstra
        double[] dist = new double[total];
        Arrays.fill(dist, Double.MAX_VALUE);
        dist[vegaNode] = 0;
        PriorityQueue<double[]> pq = new PriorityQueue<>(Comparator.comparingDouble(a -> a[0]));
        pq.offer(new double[]{0, vegaNode});
        while (!pq.isEmpty()) {
            double[] cur = pq.poll();
            double d = cur[0]; int u = (int)cur[1];
            if (d > dist[u]) continue;
            for (int v = 0; v < total; v++) {
                if (v == u) continue;
                double w = 0;
                int pu = u < N*5 ? u/5 : -1, pv = v < N*5 ? v/5 : -1;
                if (pu >= 0 && pu == pv) w = 0;
                else w = Math.hypot(pts[u][0]-pts[v][0], pts[u][1]-pts[v][1]);
                if (dist[u] + w < dist[v]) {
                    dist[v] = dist[u] + w;
                    pq.offer(new double[]{dist[v], v});
                }
            }
        }
        System.out.printf("%.6f%n", dist[altNode]);
    }
}

import java.io.*;
import java.util.*;

public class Main {

    static class Point {
        double x, y;
        Point(double x, double y) {
            this.x = x;
            this.y = y;
        }
        double distanceTo(Point other) {
            double dx = this.x - other.x;
            double dy = this.y - other.y;
            return Math.sqrt(dx * dx + dy * dy);
        }
    }

    // Generate vertices of a pentagram (star) centered at (cx, cy) with given radius
    static List<Point> getPentagramPoints(double cx, double cy, double r) {
        List<Point> points = new ArrayList<>();
        // Outer vertices of pentagram (5 points)
        for (int i = 0; i < 5; i++) {
            double angle = Math.toRadians(-90 + i * 72); // start from top
            double x = cx + r * Math.cos(angle);
            double y = cy + r * Math.sin(angle);
            points.add(new Point(x, y));
        }
        // Inner vertices (5 points) - intersections of pentagram lines
        // Inner radius = r * sin(18°) / sin(54°) ≈ r * 0.381966
        double innerR = r * Math.sin(Math.toRadians(18)) / Math.sin(Math.toRadians(54));
        for (int i = 0; i < 5; i++) {
            double angle = Math.toRadians(-90 + i * 72 + 36); // offset by 36°
            double x = cx + innerR * Math.cos(angle);
            double y = cy + innerR * Math.sin(angle);
            points.add(new Point(x, y));
        }
        return points;
    }

    // Build adjacency for a single pentagram (edges along the star lines)
    static void addPentagramEdges(List<Point> vertices, List<List<int[]>> adj, int offset) {
        int n = vertices.size(); // should be 10
        // Outer vertices 0-4, inner vertices 5-9
        // Connect each outer vertex to the two inner vertices that are 1 step away along the star
        for (int i = 0; i < 5; i++) {
            int inner1 = 5 + (i + 1) % 5; // next inner
            int inner2 = 5 + (i + 4) % 5; // previous inner
            addUndirectedEdge(adj, offset + i, offset + inner1, vertices.get(i).distanceTo(vertices.get(inner1)));
            addUndirectedEdge(adj, offset + i, offset + inner2, vertices.get(i).distanceTo(vertices.get(inner2)));
        }
        // Connect inner vertices in a pentagon (actually the inner star edges)
        // The inner vertices form a pentagon
        for (int i = 0; i < 5; i++) {
            int next = (i + 1) % 5;
            addUndirectedEdge(adj, offset + 5 + i, offset + 5 + next, 
                              vertices.get(5 + i).distanceTo(vertices.get(5 + next)));
        }
    }

    static void addUndirectedEdge(List<List<int[]>> adj, int u, int v, double w) {
        adj.get(u).add(new int[]{v, Double.valueOf(w).hashCode()}); // store weight as hash? No, better use custom class
    }

    // We'll store edges with double weight properly
    static class Edge {
        int to;
        double weight;
        Edge(int to, double weight) {
            this.to = to;
            this.weight = weight;
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        double vx = Double.parseDouble(st.nextToken());
        double vy = Double.parseDouble(st.nextToken());
        double ax = Double.parseDouble(st.nextToken());
        double ay = Double.parseDouble(st.nextToken());

        int N = Integer.parseInt(br.readLine());

        List<Point> allPoints = new ArrayList<>();
        // Start and end points
        Point start = new Point(vx, vy);
        Point end = new Point(ax, ay);
        allPoints.add(start);
        allPoints.add(end);

        // Store each pentagram's vertices for later edge building
        List<List<Point>> pentagramVertices = new ArrayList<>();
        for (int i = 0; i < N; i++) {
            st = new StringTokenizer(br.readLine());
            double cx = Double.parseDouble(st.nextToken());
            double cy = Double.parseDouble(st.nextToken());
            double r = Double.parseDouble(st.nextToken());
            List<Point> verts = getPentagramPoints(cx, cy, r);
            pentagramVertices.add(verts);
            for (Point p : verts) {
                allPoints.add(p);
            }
        }

        int totalNodes = 2 + N * 10; // start, end, N*10 pentagram vertices
        List<List<Edge>> adj = new ArrayList<>();
        for (int i = 0; i < totalNodes; i++) {
            adj.add(new ArrayList<>());
        }

        // Edges within each pentagram
        int offset = 2; // 0: start, 1: end
        for (int i = 0; i < N; i++) {
            List<Point> verts = pentagramVertices.get(i);
            int n = verts.size(); // 10
            // Add edges along pentagram lines
            for (int j = 0; j < 5; j++) {
                int inner1 = 5 + (j + 1) % 5;
                int inner2 = 5 + (j + 4) % 5;
                double w1 = verts.get(j).distanceTo(verts.get(inner1));
                double w2 = verts.get(j).distanceTo(verts.get(inner2));
                adj.get(offset + j).add(new Edge(offset + inner1, w1));
                adj.get(offset + inner1).add(new Edge(offset + j, w1));
                adj.get(offset + j).add(new Edge(offset + inner2, w2));
                adj.get(offset + inner2).add(new Edge(offset + j, w2));
            }
            for (int j = 0; j < 5; j++) {
                int next = (j + 1) % 5;
                double w = verts.get(5 + j).distanceTo(verts.get(5 + next));
                adj.get(offset + 5 + j).add(new Edge(offset + 5 + next, w));
                adj.get(offset + 5 + next).add(new Edge(offset + 5 + j, w));
            }
            offset += 10;
        }

        // Add edges from start to all pentagram vertices and end, and between all vertices (complete graph for interstellar travel)
        // Since we can travel between any two points (not on same pentagram) with energy = distance
        // But we also have edges within pentagrams with zero cost? No, within pentagram cost is also distance (but along lines)
        // Actually moving along pentagram lines uses no energy? Problem says "move along the lines of the pentacles without using energy"
        // Wait: "move along the lines of the pentacles without using energy" means traveling on the pentagram edges costs 0 energy?
        // But we already added edges with distance as weight. Actually the problem says:
        // "The spaceship used for the tour has a special engine that allows it to move along the lines of the pentacles without using energy,
        //  while moving between the pentacles requires energy proportional to the distance traveled."
        // So moving along pentagram lines costs 0 energy. Moving between pentacles (i.e., between points not on same pentagram line) costs distance.
        // So we should set weight 0 for pentagram edges.

        // Rebuild adjacency with 0 weight for pentagram edges
        adj.clear();
        for (int i = 0; i < totalNodes; i++) {
            adj.add(new ArrayList<>());
        }

        offset = 2;
        for (int i = 0; i < N; i++) {
            List<Point> verts = pentagramVertices.get(i);
            for (int j = 0; j < 5; j++) {
                int inner1 = 5 + (j + 1) % 5;
                int inner2 = 5 + (j + 4) % 5;
                adj.get(offset + j).add(new Edge(offset + inner1, 0));
                adj.get(offset + inner1).add(new Edge(offset + j, 0));
                adj.get(offset + j).add(new Edge(offset + inner2, 0));
                adj.get(offset + inner2).add(new Edge(offset + j, 0));
            }
            for (int j = 0; j < 5; j++) {
                int next = (j + 1) % 5;
                adj.get(offset + 5 + j).add(new Edge(offset + 5 + next, 0));
                adj.get(offset + 5 + next).add(new Edge(offset + 5 + j, 0));
            }
            offset += 10;
        }

        // Now add edges between all pairs of points (including start, end, and all pentagram vertices) with weight = distance
        // This represents interstellar travel (energy cost = distance)
        // Since N <= 100, total points <= 1002, O(N^2) edges is okay
        // But we can be smarter: we only need to connect each point to every other point? Actually we can travel directly between any two points
        // So complete graph is needed.
        // However, with 1002 nodes, edges = ~500k, Dijkstra O(E log V) is fine.

        for (int i = 0; i < totalNodes; i++) {
            for (int j = i + 1; j < totalNodes; j++) {
                double dist = allPoints.get(i).distanceTo(allPoints.get(j));
                // But if both points are on same pentagram, we already have zero-cost edges, 
                // but we should still allow direct interstellar travel (cost = distance) which is worse, so it won't be chosen.
                // However, if they are on same pentagram but not connected by lines? Actually all pentagram vertices are connected by lines (via zero-cost edges).
                // So direct edge with positive cost won't be used. So it's fine to add all.
                adj.get(i).add(new Edge(j, dist));
                adj.get(j).add(new Edge(i, dist));
            }
        }

        // Dijkstra from start (index 0) to end (index 1)
        double[] dist = new double[totalNodes];
        Arrays.fill(dist, Double.MAX_VALUE);
        dist[0] = 0;
        PriorityQueue<double[]> pq = new PriorityQueue<>(Comparator.comparingDouble(a -> a[1]));
        pq.offer(new double[]{0, 0});

        while (!pq.isEmpty()) {
            double[] cur = pq.poll();
            int u = (int) cur[0];
            double d = cur[1];
            if (d > dist[u]) continue;
            if (u == 1) break;
            for (Edge e : adj.get(u)) {
                if (dist[e.to] > d + e.weight) {
                    dist[e.to] = d + e.weight;
                    pq.offer(new double[]{e.to, dist[e.to]});
                }
            }
        }

        System.out.printf("%.10f%n", dist[1]);
    }
}

import java.io.*;
import java.util.*;

/*
 * Milky Way Transportation Corporation
 *
 * We are given multiple pentagrams (5-point stars) on a 2D plane.
 * Moving along the edges of any pentagram costs 0.
 * Moving through space between arbitrary points costs Euclidean distance.
 *
 * We must find the minimum total positive-distance travel from Vega to Altair.
 *
 * Key observation:
 * Since movement on pentagram edges is free, every point on those edges is effectively
 * part of a zero-cost network. The optimal path can be modeled on a graph whose nodes are:
 *   - start point
 *   - goal point
 *   - all pentagram vertices
 *   - all intersections between pentagram edges
 *
 * Consecutive points lying on the same pentagram edge are connected with 0 cost.
 * Every pair of nodes is also connectable directly through space with cost = Euclidean distance.
 *
 * Then the answer is the shortest path from start to goal.
 */
public class Main {
    static final double EPS = 1e-9;

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c != -1 && c <= ' ');
            if (c == -1) return null;
            while (c != -1 && c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }
    }

    static class Point {
        double x, y;
        int id;

        Point(double x, double y, int id) {
            this.x = x;
            this.y = y;
            this.id = id;
        }
    }

    static class Segment {
        Point a, b;

        Segment(Point a, Point b) {
            this.a = a;
            this.b = b;
        }
    }

    static class Edge {
        int to;
        double w;

        Edge(int to, double w) {
            this.to = to;
            this.w = w;
        }
    }

    static class State implements Comparable<State> {
        int v;
        double d;

        State(int v, double d) {
            this.v = v;
            this.d = d;
        }

        public int compareTo(State o) {
            return Double.compare(this.d, o.d);
        }
    }

    static double dist(Point a, Point b) {
        double dx = a.x - b.x;
        double dy = a.y - b.y;
        return Math.hypot(dx, dy);
    }

    static double cross(double ax, double ay, double bx, double by) {
        return ax * by - ay * bx;
    }

    static boolean samePoint(Point a, Point b) {
        return Math.abs(a.x - b.x) < EPS && Math.abs(a.y - b.y) < EPS;
    }

    static boolean onSegment(Point p, Segment s) {
        double cr = cross(s.b.x - s.a.x, s.b.y - s.a.y, p.x - s.a.x, p.y - s.a.y);
        if (Math.abs(cr) > 1e-8) return false;
        return Math.min(s.a.x, s.b.x) - 1e-8 <= p.x && p.x <= Math.max(s.a.x, s.b.x) + 1e-8 &&
               Math.min(s.a.y, s.b.y) - 1e-8 <= p.y && p.y <= Math.max(s.a.y, s.b.y) + 1e-8;
    }

    // Returns intersection point of two segments if they intersect at a unique point; otherwise null.
    static Point segmentIntersection(Segment s1, Segment s2) {
        double x1 = s1.a.x, y1 = s1.a.y;
        double x2 = s1.b.x, y2 = s1.b.y;
        double x3 = s2.a.x, y3 = s2.a.y;
        double x4 = s2.b.x, y4 = s2.b.y;

        double dx1 = x2 - x1, dy1 = y2 - y1;
        double dx2 = x4 - x3, dy2 = y4 - y3;

        double den = cross(dx1, dy1, dx2, dy2);

        if (Math.abs(den) < EPS) {
            // Parallel or collinear. In this problem, overlapping segments should not occur
            // in normal pentagram geometry except shared endpoints/intersection coincidences,
            // which are already represented by vertices.
            for (Point p : new Point[]{s1.a, s1.b}) {
                if (onSegment(p, s2)) return p;
            }
            for (Point p : new Point[]{s2.a, s2.b}) {
                if (onSegment(p, s1)) return p;
            }
            return null;
        }

        double t = cross(x3 - x1, y3 - y1, dx2, dy2) / den;
        double u = cross(x3 - x1, y3 - y1, dx1, dy1) / den;

        if (t < -1e-8 || t > 1 + 1e-8 || u < -1e-8 || u > 1 + 1e-8) return null;

        double ix = x1 + t * dx1;
        double iy = y1 + t * dy1;
        return new Point(ix, iy, -1);
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        String first = fs.next();
        if (first == null) return;

        int n = Integer.parseInt(first);
        double sx = fs.nextDouble();
        double sy = fs.nextDouble();
        double gx = fs.nextDouble();
        double gy = fs.nextDouble();

        ArrayList<Point> points = new ArrayList<>();
        Point start = new Point(sx, sy, 0);
        Point goal = new Point(gx, gy, 1);
        points.add(start);
        points.add(goal);

        Segment[] segs = new Segment[n * 5];
        ArrayList<Point>[] segPoints = new ArrayList[n * 5];
        for (int i = 0; i < n * 5; i++) segPoints[i] = new ArrayList<>();

        int pid = 2;

        for (int i = 0; i < n; i++) {
            Point[] v = new Point[5];
            for (int j = 0; j < 5; j++) {
                double x = fs.nextDouble();
                double y = fs.nextDouble();
                v[j] = new Point(x, y, pid++);
                points.add(v[j]);
            }

            // Pentagram edges: connect every second vertex
            // 0-2-4-1-3-0
            int[] ord = {0, 2, 4, 1, 3};
            for (int j = 0; j < 5; j++) {
                Point a = v[ord[j]];
                Point b = v[ord[(j + 1) % 5]];
                int idx = i * 5 + j;
                segs[idx] = new Segment(a, b);
                segPoints[idx].add(a);
                segPoints[idx].add(b);
            }
        }

        // Add intersections between all pentagram edges
        for (int i = 0; i < segs.length; i++) {
            for (int j = i + 1; j < segs.length; j++) {
                Point inter = segmentIntersection(segs[i], segs[j]);
                if (inter != null) {
                    Point real = new Point(inter.x, inter.y, pid++);
                    points.add(real);
                    segPoints[i].add(real);
                    segPoints[j].add(real);
                }
            }
        }

        int m = points.size();
        ArrayList<Edge>[] graph = new ArrayList[m];
        for (int i = 0; i < m; i++) graph[i] = new ArrayList<>();

        // Complete graph with Euclidean distances
        for (int i = 0; i < m; i++) {
            for (int j = i + 1; j < m; j++) {
                double d = dist(points.get(i), points.get(j));
                graph[i].add(new Edge(j, d));
                graph[j].add(new Edge(i, d));
            }
        }

        // Zero-cost edges along each segment between consecutive points on that segment
        for (int i = 0; i < segs.length; i++) {
            Segment s = segs[i];
            ArrayList<Point> list = segPoints[i];

            // Remove duplicates geometrically
            ArrayList<Point> uniq = new ArrayList<>();
            for (Point p : list) {
                boolean found = false;
                for (Point q : uniq) {
                    if (samePoint(p, q)) {
                        found = true;
                        break;
                    }
                }
                if (!found) uniq.add(p);
            }

            uniq.sort((p1, p2) -> {
                double t1, t2;
                if (Math.abs(s.a.x - s.b.x) >= Math.abs(s.a.y - s.b.y)) {
                    t1 = (Math.abs(s.a.x - s.b.x) < EPS) ? 0 : (p1.x - s.a.x) / (s.b.x - s.a.x);
                    t2 = (Math.abs(s.a.x - s.b.x) < EPS) ? 0 : (p2.x - s.a.x) / (s.b.x - s.a.x);
                } else {
                    t1 = (Math.abs(s.a.y - s.b.y) < EPS) ? 0 : (p1.y - s.a.y) / (s.b.y - s.a.y);
                    t2 = (Math.abs(s.a.y - s.b.y) < EPS) ? 0 : (p2.y - s.a.y) / (s.b.y - s.a.y);
                }
                return Double.compare(t1, t2);
            });

            for (int j = 0; j + 1 < uniq.size(); j++) {
                int u = uniq.get(j).id;
                int v = uniq.get(j + 1).id;
                graph[u].add(new Edge(v, 0.0));
                graph[v].add(new Edge(u, 0.0));
            }
        }

        // Dijkstra
        double[] d = new double[m];
        Arrays.fill(d, Double.POSITIVE_INFINITY);
        d[0] = 0.0;
        PriorityQueue<State> pq = new PriorityQueue<>();
        pq.add(new State(0, 0.0));

        while (!pq.isEmpty()) {
            State cur = pq.poll();
            if (cur.d > d[cur.v] + EPS) continue;
            if (cur.v == 1) break;
            for (Edge e : graph[cur.v]) {
                double nd = cur.d + e.w;
                if (nd + EPS < d[e.to]) {
                    d[e.to] = nd;
                    pq.add(new State(e.to, nd));
                }
            }
        }

        System.out.printf(Locale.US, "%.10f%n", d[1]);
    }
}
